mapper.update:

UPDATE LESSONS
SET LESSON_AT = #{lessonAt, jdbcType=TIMESTAMP}
WHERE ID = #{id}
	AND STUDENT_ID IN (
		SELECT S.ID
		FROM STUDENTS S
		WHERE S.INSTRUCTOR_ID = #{instructorId}
	)


UPDATE LESSONS
SET STATUS = #{status},
	STATUS_MEMO = #{statusMemo, jdbcType=VARCHAR}
WHERE ID = #{id}
	AND STUDENT_ID IN (
		SELECT S.ID
		FROM STUDENTS S
		WHERE S.INSTRUCTOR_ID = #{instructorId} 
	)

mapper.select:
SELECT DISTINCT TRUNC(L.LESSON_AT)
FROM LESSONS L
INNER JOIN STUDENTS S
	ON L.STUDENT_ID = S.ID
WHERE S.INSTRUCTOR_ID = #{instructorId}
	AND L.STATUS IN ('SCHEDULED', 'ATTENDED', 'LATE')
	AND L.LESSON_AT >= #{monthStart, jdbcType=TIMESTAMP}
	AND L.LESSON_AT < #{nextMonthStart, jdbcType=TIMESTAMP}
ORDER BY TRUNC(L.LESSON_AT) ASC
